import {canonicalURL, matchLanding, landingChecks, expectedURLs} from './landing.mjs';
const $ = (s, r=document) => r.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fetchJSON = async (url, body) => {const r=await fetch(url, body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-Local-Review':'1'},body:JSON.stringify(body)}); const v=await r.json();if(!r.ok)throw Error(v.error||'保存失败');return v;};
let D, S, revision=0, versions=[], page=0, tab='pages', queue=Promise.resolve(), saved='已保存到本机', timer;
const steps=[['接入范围','看清这次检查哪些广告'],['基础规则','按组确认，不用逐条填写'],['页面匹配','按组确认落地页规则'],['例外与缺口','只处理需要你判断的部分'],['首日版本','留下规则和第一次配置']];
const defaults=()=>({snapshot_id:D.snapshot_id,step:0,reviewer:'',scope:false,budget:false,inherit:false,features:false,gap_ack:false,page_reviewed:false,page_mode:'inherit',landing_group_ok:[],pages:[],feature_rule_keys:D.features.filter(f=>f.checkable).map(f=>f.key),allowed_features:[],material_ok:[],material_flags:{},instagram_rules:(D.identity_summary?.groups||[]).filter(g=>g.instagram_known).map(g=>({country:g.country,allowed_ids:g.recommended_instagram_id?[g.recommended_instagram_id]:[],confirmed:false})),identity_rules:(D.identity_summary?.groups||[]).map(g=>({country:g.country,allowed_fb_ids:g.recommended_page_id?[g.recommended_page_id]:[],confirmed:false})),fb:'',ig:'',partnership:true,promo_date:'',promo_tag:'BF',
 markets:[{pattern:'de_demo_',value:'DE',confirmed:false},{pattern:'fr_demo_',value:'FR',confirmed:false}],
 languages:[{pattern:'de_demo_',value:'德语',confirmed:false},{pattern:'fr_demo_',value:'法语',confirmed:false}]});
const badge=(text,kind='')=>`<span class="badge ${kind}">${text}</span>`;
const check=(key,text,detail='')=>`<label class="check"><input type="checkbox" data-root="${key}" ${S[key]?'checked':''}><span>${text}${detail?`<small>${detail}</small>`:''}</span></label>`;
const metric=(n,label)=>`<div class="metric"><strong>${n}</strong><span>${label}</span></div>`;
const btn=(text,action,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const statusBadge=a=>badge(a.scope_status==='ACTIVE'?'接口显示在投':a.scope_status==='PENDING'?'准备中 · 本次排除':a.scope_status==='CONFLICT'?'状态待核实 · 已隔离':'未纳入核查',a.scope_status==='ACTIVE'?'green':'amber');
const nameList=(ads)=>`<details class="names"><summary>展开对应广告 · ${ads.length} 条</summary><div class="name-scroll">${ads.map(a=>`<div class="name-row"><strong>${esc(a.name)}</strong> ${statusBadge(a)}<small>${esc(a.campaign_name)}<br>Ad Set：${esc(a.adset_name)}</small></div>`).join('')}</div></details>`;
const campaignsFor=r=>D.campaigns.filter(c=>r.pattern.trim() && c.name.toLowerCase().includes(r.pattern.trim().toLowerCase()));
const adsFor=r=>{const ids=new Set(campaignsFor(r).map(c=>c.id));return D.ads.filter(a=>ids.has(a.campaign_id));};
function matches(a,r){return matchLanding(a,r);}
const pageAds=r=>D.ads.filter(a=>matches(a,r));
function issues(){
 let list=[];
 for(const r of S.markets.filter(r=>r.confirmed)){const allowed=r.value.toUpperCase().split(/[,，\s]+/).filter(Boolean);const bad=adsFor(r).filter(a=>a.countries.some(c=>!allowed.includes(c)));if(bad.length)list.push({type:'配置不符',title:`市场规则与 ${bad.length} 条广告不一致`,detail:`名称包含 ${r.pattern} 应投 ${r.value}；实际包含其他国家。`,ads:bad,step:1});}
 for(const [key,label] of [['markets','市场'],['languages','语言']]){
  const rs=S[key].filter(r=>r.confirmed),uncovered=D.campaigns.filter(c=>!rs.some(r=>campaignsFor(r).some(x=>x.id===c.id)));
  if(rs.length && uncovered.length)list.push({type:'待补规则',title:`${uncovered.length} 个 Campaign 未匹配${label}规则`,detail:uncovered.map(c=>c.name).join('；'),step:1});
  const conflict=D.campaigns.filter(c=>new Set(rs.filter(r=>campaignsFor(r).some(x=>x.id===c.id)).map(r=>r.value.trim().toLowerCase())).size>1);
  if(conflict.length)list.push({type:'规则冲突',title:`${label}规则有重叠`,detail:conflict.map(c=>c.name).join('；'),step:1});
 }
 if(S.page_mode==='rules'){
  const checks=landingChecks(D.ads,S.pages);
  for(const [status,type,title] of [['MISSING_RULE','待补规则','广告没有匹配页面规则'],['UNCONFIRMED_RULE','待确认','页面规则尚未确认'],['INVALID_RULE','规则格式','页面规则的网址格式有误'],['RULE_CONFLICT','规则冲突','广告同时匹配不同页面规则'],['UNREADABLE','检查不到','广告实际落地页检查不到'],['URL_MISMATCH','配置不符','实际落地页不符合已确认规则']]){
   const rows=checks.filter(c=>c.status===status);if(rows.length)list.push({type,title:`${rows.length} 条${title}`,detail:status==='URL_MISMATCH'?'展开广告查看实际链接；请调整广告后台或修改规则后重新确认。':'在页面匹配中处理。',ads:D.ads.filter(a=>rows.some(c=>c.ad_id===a.id)),landing:true,landing_checks:rows,step:2});
  }
 }
 for(const [key,reason] of Object.entries(S.material_flags||{})){const g=D.material_groups.find(g=>g.key===key);if(g)list.push({type:'人工待复核',title:`素材文案搭配：${g.name}`,detail:reason||'负责人标记为需要复核。',ads:D.ads.filter(a=>g.ad_ids.includes(a.id)),step:2});}
 for(const r of S.identity_rules.filter(r=>r.confirmed)){const bad=D.ads.filter(a=>a.countries.includes(r.country)&&a.identity?.facebook_page_id&&!r.allowed_fb_ids.includes(a.identity.facebook_page_id));if(bad.length)list.push({type:'主页待核验',title:`${r.country} 有 ${bad.length} 条广告帖子归属不在允许名单`,detail:'先核对是否为合作广告或允许的例外，暂不直接判定主页挂错。',ads:bad,step:1});}
 for(const r of S.instagram_rules.filter(r=>r.confirmed)){const bad=D.ads.filter(a=>a.countries.includes(r.country)&&a.identity?.instagram_account_id&&!r.allowed_ids.includes(a.identity.instagram_account_id));if(bad.length)list.push({type:'账号待核验',title:`${r.country} 有 ${bad.length} 条广告的 Instagram 账号不在允许名单`,detail:'先核对是否为合作广告或允许的例外，暂不直接判定账号挂错。',ads:bad,step:1});}
 return list;
}
function readiness(){let missing=[];if(S.page_mode==='inherit'&&(D.landing_groups||[]).some(g=>!S.landing_group_ok.includes(g.key)))missing.push('按组确认当前落地页');if(S.instagram_rules.some(r=>!r.confirmed||!r.allowed_ids.length))missing.push('确认 Instagram 账号分组');if((D.identity_summary?.groups||[]).some(g=>!S.identity_rules.some(r=>r.country===g.country&&r.confirmed&&r.allowed_fb_ids.length)))missing.push('确认 Facebook 主页分组');if(D.status_conflicts?.unresolved)missing.push('核实 Campaign 状态冲突（当前仅保存草稿）');if(!S.reviewer.trim())missing.push('填写确认人');for(const [k,l] of [['scope','确认接入范围'],['budget','确认预算'],['inherit','确认首日继承'],['gap_ack','确认待补查内容'],['page_reviewed','确认页面接入方式']])if(!S[k])missing.push(l);for(const [k,l] of [['markets','市场'],['languages','语言']])if(S[k].some(r=>!r.confirmed||!r.pattern.trim()||!r.value.trim()))missing.push(`确认${l}分组`);if(S.page_mode==='rules'&&(!S.pages.length||S.pages.some(r=>!r.confirmed||!r.value.trim()||!r.url.trim())))missing.push('确认页面规则');return missing;}
function stageDone(i){return [S.scope&&S.reviewer.trim(),S.budget&&S.inherit&&S.instagram_rules.every(r=>r.confirmed)&&S.identity_rules.every(r=>r.confirmed)&&S.markets.every(r=>r.confirmed)&&S.languages.every(r=>r.confirmed),S.page_reviewed&&((S.page_mode==='inherit'&&(D.landing_groups||[]).every(g=>S.landing_group_ok.includes(g.key)))||(S.pages.length&&S.pages.every(r=>r.confirmed))),S.gap_ack,versions.some(v=>JSON.stringify({...v.rules_and_confirmations,step:0})===JSON.stringify({...S,step:0}))][i];}
function render(){
 const current=S.step;
 $('#app').innerHTML=`<aside><a class="brand" href="#"><span class="brand-mark">e</span><span>demo <small>广告配置检查</small></span></a><a href="/workflow-v2.html#capabilities" style="display:block;margin-top:22px;color:#23634e;font-size:12px">← 能力介绍与 P0 检查项</a><div class="side-label">首次接入 · 负责人确认</div><nav>${steps.map((s,i)=>`<button class="step ${i===current?'active':''}" data-action="step" data-index="${i}" ${i===current?'aria-current="step"':''}><span class="step-num">${stageDone(i)?'✓':i+1}</span><span>${s[0]}<small>${s[1]}</small></span></button>`).join('')}</nav>${versions.length?'<a href="first-day/" style="display:block;padding:14px;color:#23634e">第一天检查报告 →</a>':''}<a href="phase-rules/" style="display:block;padding:14px;color:#23634e">阶段规则 · 对话补充 →</a><div class="sidebar-note"><span class="dot"></span> 本机测试 · 无需登录<p>只读取广告配置<br>这里的确认不会修改广告后台</p></div></aside>
 <div class="workspace"><header><div><span class="eyebrow">demo E1 / 首次接入</span><div class="account">${esc(D.account)} ${badge('示例配置（虚构）','green')}</div></div><span class="save-state">${esc(saved)}</span></header>
 <main><div class="page-title"><div class="eyebrow">STEP 0${current+1} / 05</div><h1>${['先看清这次接入什么','一组确认，一起生效','让条件与对应内容对得上','把需要判断的留在这里','把今天的确认，留成标准'][current]}</h1><p>${['系统先整理，负责人确认范围。接下来的规则会应用到这批广告。','市场、语言、主页、页面分别确定；不把它们强行绑在一起。','看一组的匹配关系，展开后再看对应的 Campaign、Ad Set 和 Ad。','规则不符、未补规则和数据没读到，分开处理。','已确认规则 + 首日实际配置 + 尚未完成的项目，一起保存。'][current]}</p></div>
 ${[scopeView,ruleView,mappingView,exceptionsView,baselineView][current]()}
 <div class="bottom-bar"><span>${current===4?'版本留在本机，可下载迁移。':'修改会自动保存在本机，随时可回来继续。'}</span><div>${current>0?btn('上一步','prev'):''}${current<4?btn(['开始按组确认 →','继续看匹配关系 →','查看例外与缺口 →','查看首日版本 →'][current],'next','primary'):''}</div></div></main></div>`;
}
function scopeView(){return `${S.scope_change_notice?`<div class="notice subtle">${esc(S.scope_change_notice)}</div>`:''}<div class="metrics">${metric(D.counts.campaigns,'Campaign')}${metric(D.counts.adsets,'Ad Set')}${metric(D.counts.ads,D.status_conflicts?.unresolved?'接口在投候选 Ad':'正在投放的 Ad')}${metric(D.counts.creatives,'Creative')}</div>
 ${D.status_conflicts?.unresolved?`<div class="notice amber"><strong>3 个 Campaign 的状态与负责人反馈不一致</strong><p>这三项及其下属广告已移出主核查。接口与 Meta 后台开关均显示开启；正等待澄清负责人所指的投放范围。当前只保存草稿，不生成首日版本。</p><details><summary>查看这 3 个待核实 Campaign</summary>${D.status_conflicts.campaigns.map(c=>`<div class="name-row">${esc(c.name)}<small>负责人反馈：没有在投 · 接口返回：ACTIVE</small></div>`).join('')}</details></div>`:''}
 <div class="notice subtle"><strong>${D.status_conflicts?.unresolved?'候选范围':'本次范围'}：${D.scope_summary.included} 条${D.status_conflicts?.unresolved?'':'正在投放'} · ${D.scope_summary.excluded} 条已单列排除</strong><p>Campaign、Ad Set 和 Ad 的开关与投放状态一起核对。准备中与负责人反馈有冲突的广告，均不混入本次主列表；不使用是否有花费来筛选。</p><small>状态复核：${new Date(D.scope_summary.checked_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}（北京时间） · 当前已保存的状态，非实时更新</small><details><summary>查看已排除的 ${D.excluded_ads.length} 条广告（不计入本次标准版）</summary>${nameList(D.excluded_ads)}</details></div>
 <section><div class="section-head"><h2>这批广告来自哪里</h2>${badge(D.status_conflicts?.unresolved?'状态核对未完成':'接口三层状态为开启',D.status_conflicts?.unresolved?'amber':'green')}</div><div class="two-col"><div><label class="field-label" for="reviewer">由谁确认</label><input id="reviewer" data-root="reviewer" placeholder="填写你的名字" value="${esc(S.reviewer)}"><p class="muted">每一版会留下确认人和保存时间。</p></div><div class="fact-list"><p><span>账户</span><b>${esc(D.account)}</b></p><p><span>配置采集</span><b>${esc(D.captured_at)}</b></p><p><span>账户时区 / 币种</span><b>${esc(D.timezone)} / ${D.currency}</b></p></div></div>
 <div class="market-preview">${[['DE','德国'],['FR','法国']].map(([code,title])=>{const c=D.campaigns.filter(c=>c.countries.includes(code));return `<div><span class="country">${code}</span><div><h3>${title}</h3><p>${c.length} 个 Campaign · ${c.reduce((n,c)=>n+c.ad_count,0)} 条 Ad</p></div></div>`;}).join('')}</div>
 <details><summary>展开全部 ${D.counts.campaigns} 个 Campaign</summary><div class="table-wrap"><table><thead><tr><th>Campaign 名称</th><th>实际国家</th><th>Ad Set / Ad</th></tr></thead><tbody>${D.campaigns.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.countries.join(', ')}</td><td>${c.adset_count} / ${c.ad_count}</td></tr>`).join('')}</tbody></table></div></details>${check('scope','确认这是本次要接入的账户和广告范围')}</section>
 <div class="notice amber"><strong>先知道这次能确认到哪里</strong><p>国家、预算、人群等配置已读到；正文只取回 ${D.coverage.body} / ${D.counts.ads} 条广告。Facebook 帖子归属主页已整理；Instagram 账号名称已按实际取数展示；实际落地页已补齐；合作双方身份、UTM 目前检查不到；AI 创意增强已暂时移出检查范围。这里展示的是已保存的配置，不是实时后台。</p></div>`;}
function groupRules(key,title,description){return `<section><div class="section-head"><div><h2>${title}</h2><p>${description}</p></div>${btn('确认全部分组','confirm-groups','secondary',`data-key="${key}"`)}</div><div class="rule-grid">${S[key].map((r,i)=>{const cs=campaignsFor(r),aa=adsFor(r);return `<article class="group-card ${r.confirmed?'confirmed':''}"><div class="section-head"><h3>${key==='markets'?'投放市场':'广告语言'} ${i+1}</h3>${badge(r.confirmed?'已确认':'待确认',r.confirmed?'green':'amber')}</div><label class="field-label">Campaign 名称包含</label><input data-group="${key}" data-index="${i}" data-field="pattern" value="${esc(r.pattern)}"><label class="field-label">${key==='markets'?'允许投放国家（国家代码，逗号分开）':'允许文案语言'}</label><input data-group="${key}" data-index="${i}" data-field="value" value="${esc(r.value)}"><p class="match-count">匹配 ${cs.length} 个 Campaign · ${aa.length} 条 Ad</p><details><summary>看这组 Campaign</summary>${cs.map(c=>`<div class="name-row">${esc(c.name)}<small>实际国家：${c.countries.join(', ')} · ${c.ad_count} 条 Ad</small></div>`).join('')||'<p>没有匹配到 Campaign。</p>'}</details><div class="actions">${btn(r.confirmed?'撤回确认':'这组没问题','confirm-group',r.confirmed?'quiet':'primary',`data-key="${key}" data-index="${i}"`)}${btn('删除分组','remove-group','quiet',`data-key="${key}" data-index="${i}"`)}</div></article>`;}).join('')}</div><p class="muted">${key==='languages'?'语言按命名生成待确认规则，不代表全部广告正文已经完成语言检查。':'名称筛选忽略大小写；这里确定应该投哪里，再与实际地区设置比对。'}</p>${btn('+ 增加一组','add-group','quiet',`data-key="${key}"`)}</section>`;}
function ruleView(){return groupRules('markets','01 · 国家按组确认','同一账户可以有不同市场，每组只管自己匹配到的 Campaign。')+groupRules('languages','02 · 语言单独确认','先按市场命名给出建议，你可以单独改筛选条件和语言。')+`
 <section><div class="section-head"><div><h2>03 · 预算与启用状态</h2><p>以当前已读到的配置为起点；以后金额、预算类型或开关有变化，就列出调整。</p></div>${badge('P0')}</div><div class="budget-list">${D.campaigns.map(c=>`<div><span>${esc(c.short)}<small>${esc(c.name)}</small></span><b>${esc(c.daily_budget?.value??'未读到')} <small>${esc(c.daily_budget?.unit??'')} / 天</small></b></div>`).join('')}</div>${check('budget','这些初始预算和启用状态符合目前计划','预算按后台返回的金额显示；出价策略、归因等低优先级设置另行继承。')}</section>
 ${identityView()}
 <section><h2>当前能力边界</h2><p>AI 创意增强功能暂不纳入接入确认与检查报告，也不影响完成接入。已保存的历史配置和报告保留。</p></section>
 <section><h2>06 · 其他设置先沿用今天</h2><p>人群、版位、优化与出价、归因窗口，以及已读到的广告内容，先保存为第一次对照。确认继承仅代表以后比较变化，不代表这些内容已经逐项审过。</p>${check('inherit','同意将已读到的其他配置作为首日对照','人群属于 P1；版位、优化与出价、归因窗口属于 P2。未读到的字段不继承为空。')}<details><summary>有促销结束时间的话，在这里补充</summary><div class="two-col"><div><label class="field-label">名称中的促销标识</label><input data-root="promo_tag" value="${esc(S.promo_tag)}"></div><div><label class="field-label">最晚停投时间（账户时区）</label><input type="datetime-local" data-root="promo_date" value="${esc(S.promo_date)}"></div></div><p class="muted">BF 只作为待确认线索。没有填写截止日期时，不会凭名称判断已过期。</p></details></section>`;}
function identityView(){
 const info=D.identity_summary,labels={DE:'德国',FR:'法国',UNKNOWN:'国家待补齐'};
 return `<section id="identity-section"><div class="section-head"><div><h2>04 · 主页与账号，按组确认</h2><p>按广告实际投放国家整理。使用最多的主页先作为建议，只把少数不同的留下来核对。</p></div>${btn('确认全部 Facebook 分组','confirm-identities','secondary')}</div>
 <div class="identity-stats"><span><b>${info.facebook_named_count} / ${D.counts.ads}</b> Facebook 帖子归属已识别</span><span><b>${info.groups.length} 组</b> 国家对应建议</span><span><b>${info.instagram_identity_count} / ${D.counts.ads}</b> Instagram 账号已识别</span></div>
 <div class="rule-grid">${info.groups.map(g=>{const r=S.identity_rules.find(r=>r.country===g.country),top=g.pages.find(p=>p.page_id===g.recommended_page_id),aa=D.ads.filter(a=>g.ad_ids.includes(a.id));return `<article class="group-card identity-card ${r.confirmed?'confirmed':''}"><div class="section-head"><div><span class="eyebrow">${esc(g.country)}</span><h3>${esc(labels[g.country]||g.country)} · ${g.total} 条 Ad</h3></div>${badge(r.confirmed?'规则已确认':'系统建议 · 待确认',r.confirmed?'green':'amber')}</div><div class="identity-recommendation"><small>Facebook 主页建议</small><strong>${esc(top?.name||'暂无多数建议')}</strong><span>${top?`${top.count} / ${g.total} 条广告 · ${(top.share*100).toFixed(0)}% 使用该帖子归属主页`:'当前分布不足以自动推荐，请查看明细后选择'}</span><div class="identity-meter"><i style="width:${top?top.share*100:0}%"></i></div></div>
 <p class="muted">${g.exception_count?`${g.exception_count} 条与多数不同或尚未识别，需单独核对。`:'本组没有发现其他帖子归属主页。'}</p><p class="identity-allowed">拟允许：${r.allowed_fb_ids.length?r.allowed_fb_ids.map(id=>esc(info.account_available_pages.find(p=>p.page_id===id)?.page_name||id)).join('、'):'尚未选择'}</p>
 <details><summary>调整本组允许的主页（可多选）</summary><p class="muted">以下为账户可用主页。没有使用条数的，不表示当前广告正在使用。</p>${info.account_available_pages.map(p=>{const used=g.pages.find(x=>x.page_id===p.page_id);return `<label class="identity-option"><input type="checkbox" data-identity-country="${esc(g.country)}" data-identity-page="${esc(p.page_id)}" ${r.allowed_fb_ids.includes(p.page_id)?'checked':''}><span>${esc(p.page_name)}<small>${used?`本组 ${used.count} 条广告`:'账户可用，本组未观察到使用'}</small></span></label>`;}).join('')}</details>
 ${nameList(aa)}<details><summary>查看主页标识与识别依据</summary>${g.pages.map(p=>`<p class="muted">${esc(p.name||'名称待补齐')} · Page ID：${esc(p.page_id)}</p>`).join('')}<p class="muted">通过广告 Creative 的有效帖子归属匹配主页目录；这不代表 Partnership 合作双方身份已核实。</p></details>
 ${btn(r.confirmed?'撤回 Facebook 确认':'这个 Facebook 主页没问题','confirm-identity',r.confirmed?'secondary':'primary',`data-country="${esc(g.country)}"`)}
 ${instagramView(g)}</article>`;}).join('')}</div>
 <div class="notice subtle">同一国家可以允许多个主页；同一个主页也可以用于多个国家。点击确认只保存对应规则，不会修改广告。</div>
 ${check('partnership','合作广告单独核对','能确认是 Partnership，且包含允许的品牌身份时，再核对合作方；合作方不会自动进入普通广告允许名单。')}<p class="muted">当前接口没有完整返回合作标识与双方身份，因此本轮尚不能自动识别全部合作广告，也不能根据主页名称猜测。</p>
 <details><summary>Instagram 名称从哪里来</summary><p class="muted">从 Meta 广告后台导出逐条广告配置，按 Ad ID 关联 Instagram 账号 ID；账号名称在同一广告的身份区核对。已关联 ${info.instagram_named_count||0} / ${D.counts.ads} 条广告。没有按 Facebook 主页或国家猜测账号。此补取是后台导出，不代表接口自动拉取已接通。</p></details>
 ${S.fb||S.ig?`<details><summary>之前填写的品牌信息（已保留，未验证）</summary><p>${esc(S.fb)} ${esc(S.ig)}</p></details>`:''}
 </section>`;
}
function instagramView(g){
 const r=S.instagram_rules.find(r=>r.country===g.country),accounts=g.instagram_accounts||[],top=accounts.find(a=>a.account_id===g.recommended_instagram_id);
 if(!accounts.length)return `<div class="identity-ig"><b>Instagram 账号</b>${badge('待补齐','amber')}</div>`;
 return `<div class="identity-ig"><div class="section-head"><b>Instagram 账号建议</b>${badge(r?.confirmed?'账号规则已确认':'待你确认',r?.confirmed?'green':'amber')}</div><div class="identity-recommendation"><strong>${top?'@'+esc(top.username):'暂无多数建议'}</strong><span>${top?`${top.count} / ${g.total} 条广告 · ${(top.share*100).toFixed(0)}%`:'请根据下面的实际账号分布确认'}</span><div class="identity-meter"><i style="width:${top?top.share*100:0}%"></i></div></div><p>${g.instagram_known===g.total?'本组所有广告均已关联到实际 Instagram 账号。':`已关联 ${g.instagram_known} / ${g.total} 条，其余仍待补齐。`}</p><p class="identity-allowed">拟允许：${r?.allowed_ids.length?r.allowed_ids.map(id=>'@'+esc(D.identity_summary.instagram_accounts.find(a=>a.account_id===id)?.username||'名称待补齐')).join('、'):'尚未选择'}</p><details><summary>调整允许的 Instagram 账号（可多选）</summary>${D.identity_summary.instagram_accounts.map(a=>`<label class="identity-option"><input type="checkbox" data-ig-country="${esc(g.country)}" data-ig-id="${esc(a.account_id)}" ${r?.allowed_ids.includes(a.account_id)?'checked':''}><span>@${esc(a.username)}<small>本组 ${accounts.find(x=>x.account_id===a.account_id)?.count||0} 条广告</small></span></label>`).join('')}</details><details><summary>按账号查看对应广告</summary>${accounts.map(a=>`<h4>@${esc(a.username||'名称待补齐')} · ${a.count} 条</h4>${nameList(D.ads.filter(ad=>a.ad_ids.includes(ad.id)))}`).join('')}</details><details><summary>账号标识与取数依据</summary>${accounts.map(a=>`<p>@${esc(a.username||'名称待补齐')} · ID：${esc(a.account_id)}</p>`).join('')}<p>广告后台配置导出的 Instagram Account ID 与同一广告身份区名称关联。合作双方身份另行核对。</p></details>${btn(r?.confirmed?'撤回 Instagram 确认':'这个 Instagram 账号没问题','confirm-instagram',r?.confirmed?'secondary':'primary',`data-country="${esc(g.country)}"`)}</div>`;
}
function enhancementView(){
 const known=D.features.filter(f=>f.checkable),unknown=D.features.filter(f=>!f.checkable),enabled=known.filter(f=>f.enabled_count),off=known.filter(f=>f.disabled_count);
 return `<section id="enhancement-section"><div class="section-head"><div><h2>05 · 增强功能：先看状态，再确认允许项</h2><p>勾选表示允许开启，不是广告后台的开关。本次只确认下面 ${known.length} 项；未勾选的在确认后视为不允许。</p></div>${badge(S.features?'清单已确认':'待确认',S.features?'green':'amber')}</div><div class="identity-stats"><span><b>${enabled.length} 项</b>发现已开启</span><span><b>${off.length} 项</b>有明确关闭记录</span><span><b>${unknown.length} 项</b>所有广告都检查不到</span></div><p class="muted">每项都按本次 ${D.counts.ads} 条广告统计。只有明确的关闭记录才算关闭；检查不到的广告不参与通过或报错判断。</p><div class="feature-list">${known.map(featureRow).join('')}</div><div class="actions">${btn(`勾选当前已开启的 ${enabled.length} 项`,'allow-observed')}${btn(S.features?'已确认 · 点击撤回':'确认这份允许清单','confirm-features','primary')}</div><div class="feature-unavailable"><h3>这些功能目前检查不到 · ${unknown.length} 项</h3><p>不参与本次确认，也不会判断为关闭或检查通过。</p><details><summary>展开检查不到的功能清单</summary>${[...new Set(unknown.map(f=>f.category_label))].map(cat=>`<h4>${esc(cat)}</h4><ul>${unknown.filter(f=>f.category_label===cat).map(f=>`<li>${esc(f.label)} <small>${esc(f.key)}</small></li>`).join('')}</ul>`).join('')}</details><p class="muted">这是目前登记的功能清单，不代表 Meta 的全部功能。后续能检查到的新项会单独请你确认。</p></div></section>`;
}
function featureRow(f){
 const knownAds=D.ads.filter(a=>['ENABLED','DISABLED'].includes(a.feature_states?.[f.key]));
 return `<div class="feature-row"><label><input type="checkbox" data-feature="${esc(f.key)}" ${S.allowed_features.includes(f.key)?'checked':''}><span>${esc(f.label)}${f.child?' · 子设置':''}<small>${esc(f.key)}</small></span></label><div class="feature-status">${badge(`已开启 ${f.enabled_count} 条`,f.enabled_count?'amber':'')}${badge(`明确关闭 ${f.disabled_count} 条`,f.disabled_count?'green':'')}<small>检查不到 ${f.unknown_count} 条</small></div><details><summary>查看对应广告和状态</summary><div class="name-scroll">${knownAds.map(a=>`<div class="name-row"><strong>${esc(a.name)}</strong> ${badge(a.feature_states[f.key]==='ENABLED'?'已开启':'明确关闭',a.feature_states[f.key]==='ENABLED'?'amber':'green')}<small>${esc(a.campaign_name)}<br>Ad Set：${esc(a.adset_name)}</small></div>`).join('')}</div>${f.unknown_count?nameList(D.ads.filter(a=>!['ENABLED','DISABLED'].includes(a.feature_states?.[f.key]))).replace('展开对应广告','检查不到状态的广告'):''}</details></div>`;
}
function conditionForm(r,i,second=false){const suffix=second?'2':'';return `<div class="condition"><select aria-label="筛选层级" data-page="${i}" data-field="field${suffix}">${[['campaign','Campaign 名称'],['adset','Ad Set 名称'],['ad','Ad 名称']].map(([v,l])=>`<option value="${v}" ${r['field'+suffix]===v?'selected':''}>${l}</option>`).join('')}</select><select aria-label="筛选方式" data-page="${i}" data-field="op${suffix}">${[['contains','包含'],['not_contains','不包含'],['equals','等于'],['not_equals','不等于']].map(([v,l])=>`<option value="${v}" ${r['op'+suffix]===v?'selected':''}>${l}</option>`).join('')}</select><input aria-label="筛选词" data-page="${i}" data-field="value${suffix}" value="${esc(r['value'+suffix])}" placeholder="输入命名里的词"></div>`;}
function mappingView(){return pagesView();}
const landingName=g=>{const path=new URL(g.urls[0]).pathname;const country=path.startsWith('/eu-de/')?'德国':path.startsWith('/eu-fr/')?'法国':'页面';return country+' · '+(path.includes('black-friday')?'黑五活动页':path.includes('/products/')?'E1 商品页':/kleinunternehmen|petite-entreprise/.test(path)?'小企业页':'E1 介绍页');};
const conditionText=r=>{const field={campaign:'Campaign 名称',adset:'Ad Set 名称',ad:'Ad 名称'},op={contains:'包含',not_contains:'不包含',equals:'等于',not_equals:'不等于'};return `${field[r.field]} ${op[r.op]}「${r.value}」${r.second?`，且 ${field[r.field2]} ${op[r.op2]}「${r.value2}」`:''}`;};
function landingAdList(ads,checks=[]){return `<details class="names"><summary>查看对应 Campaign、Ad Set 和 Ad · ${ads.length} 条</summary><div class="name-scroll">${ads.map(a=>`<div class="name-row"><strong>${esc(a.name)}</strong><small>Campaign：${esc(a.campaign_name)}<br>Ad Set：${esc(a.adset_name)}</small>${(checks.find(c=>c.ad_id===a.id)?.allowed_urls||[]).map(u=>`<p class="actual-url">规则允许：${esc(u)}</p>`).join('')}${(a.landing_urls||[]).map(u=>`<p class="actual-url">实际页面：${esc(u)}</p>`).join('')}</div>`).join('')}</div></details>`;}
function landingGroupsView(){return `<div class="landing-groups">${(D.landing_groups||[]).map(g=>`<article class="landing-group ${S.landing_group_ok.includes(g.key)?'confirmed':''}"><div class="section-head"><div><h3>${esc(landingName(g))}</h3><p>${g.count} 条 Ad · ${g.campaign_names.length} 个 Campaign · ${g.adset_names.length} 种 Ad Set 名称</p></div>${badge(S.page_mode==='inherit'&&S.landing_group_ok.includes(g.key)?'当前页面已确认':'系统整理',S.page_mode==='inherit'&&S.landing_group_ok.includes(g.key)?'green':'')}</div>${g.urls.map(u=>`<p class="landing-url">${esc(u)}</p>`).join('')}<div class="landing-conditions"><b>当前广告的命名规律</b>${g.suggested_rules.map(r=>`<p>${esc(conditionText(r))} <small>· 覆盖 ${r.matched_count} 条</small></p>`).join('')}<small>以上条件任一满足即可；已与本次全部广告核对，未混入其他页面。新广告仍需重新核对。</small></div>${landingAdList(D.ads.filter(a=>g.ad_ids.includes(a.id)))}${S.page_mode==='inherit'?btn(S.landing_group_ok.includes(g.key)?'撤回这组确认':'这组当前页面没问题','confirm-landing-group',S.landing_group_ok.includes(g.key)?'secondary':'primary',`data-key="${g.key}"`):''}</article>`).join('')}</div>`;}
function pagesView(){
 const groups=D.landing_groups||[],checks=S.page_mode==='rules'?landingChecks(D.ads,S.pages):[],bad=checks.filter(c=>c.status==='URL_MISMATCH');
 return `<section id="landing-section"><div class="section-head"><div><h2>先确定：哪些广告应该去哪一页</h2><p>系统已按实际落地页归成 ${groups.length} 组。页面名称按网址整理，是否符合业务安排由你确认。</p></div>${badge(`实际页面 ${D.coverage.urls} / ${D.counts.ads}`,D.coverage.urls===D.counts.ads?'green':'amber')}</div><div class="notice subtle"><strong>${D.coverage.urls} 条广告已关联到配置中的落地页</strong><p>来源：当前载入的数据快照；分享版默认使用虚构示例。这里核对广告设置的页面，不检查网页是否能打开或跳转是否安全。</p></div><div class="choice-row"><label><input type="radio" name="page_mode" value="inherit" ${S.page_mode==='inherit'?'checked':''}> 按组确认当前页面，作为首日对照</label><label><input type="radio" name="page_mode" value="rules" ${S.page_mode==='rules'?'checked':''}> 按名称规则核对页面</label></div><div class="actions">${btn('把系统建议填入命名规则','use-landing-suggestions')}${S.page_mode==='inherit'?btn(`确认全部 ${groups.length} 组当前页面`,'confirm-all-landing'):''}</div><p class="muted">直接确认当前页面：后续新增广告或更换页面需再确认。使用命名规则：以后广告符合这些条件时，继续核对它是否去了指定页面。两种方式都不会修改广告。</p>${S.page_mode==='inherit'?`<p class="match-count">已确认 ${groups.filter(g=>S.landing_group_ok.includes(g.key)).length} / ${groups.length} 组</p>`:`<div id="landing-check-summary" class="notice ${bad.length?'amber':'subtle'}">${checks.filter(c=>c.status==='MATCH').length} 条符合已确认规则 · ${bad.length} 条页面不符 · ${checks.filter(c=>!['MATCH','URL_MISMATCH'].includes(c.status)).length} 条尚未完成核对</div>`}${landingGroupsView()}${S.page_mode==='rules'?`<h2>页面匹配规则</h2>${S.pages.map((r,i)=>{const preview=landingChecks(pageAds(r),[{...r,confirmed:true}]);return `<article class="page-rule"><div class="section-head"><h3>规则 ${i+1}</h3>${badge(r.confirmed?'已确认':'待确认',r.confirmed?'green':'amber')}${btn('删除','remove-page','quiet',`data-index="${i}"`)}</div>${conditionForm(r,i)}<label class="check compact"><input type="checkbox" data-page="${i}" data-field="second" ${r.second?'checked':''}>再加一个条件（同时满足 AND）</label>${r.second?conditionForm(r,i,true):''}<label class="field-label">允许的落地页（完整网址，一行一个）</label><textarea data-page="${i}" data-field="url" placeholder="https://品牌网站/产品页面">${esc(r.url)}</textarea><p class="muted">忽略 UTM 等追踪参数和末尾斜杠；站点、页面路径及业务参数需要一致。</p><p class="match-count">匹配 ${pageAds(r).length} 条 Ad；预览：${preview.filter(c=>c.status==='MATCH').length} 条页面相符，${preview.filter(c=>c.status==='URL_MISMATCH').length} 条页面不同。${r.confirmed?'':'确认后才按此规则判断。'}</p>${landingAdList(pageAds(r))}${btn(r.confirmed?'撤回确认':'确认这条对应关系','confirm-page',r.confirmed?'secondary':'primary',`data-index="${i}"`)}</article>`;}).join('')}${btn('+ 添加页面规则','add-page')}`:''}${check('page_reviewed','确认按上面的方式接入页面检查','只保存已确认的对应关系；没有确认的继续列出。')}<details><summary>取数时间与检查范围</summary><p>页面补取：${new Date(D.landing_source).toLocaleString('zh-CN')}。原有广告范围不变；按精确广告标识与父级名称关联。原始 URL 保留，预览链接不作为落地页。本次为已保存配置，未接通自动刷新。</p></details></section>`;
}
function materialsView(){return `<section><h2>以品牌 Media Plan 为素材文案标准</h2><p>明确的素材与文案对应关系直接录入，不再要求投手逐组确认英语、法语或德语搭配。</p><div class="notice subtle">新流程只处理读取失败、来源关系不明、执行差异和品牌资料冲突。已有手工确认记录保留为历史，不转换为品牌提供的依据。</div><a href="media-plan/" class="primary" style="display:inline-block;padding:14px 20px;background:#23634e;color:white;border-radius:8px">导入 Media Plan 并开始核对 →</a><p class="muted" style="margin-top:16px">独立本地测试模块，尚未覆盖当前账户首日标准；素材 OCR、网页读取及实时广告同步仍需接通。</p></section>`;}
function exceptionsView(){const list=issues();return `<div class="metrics three">${metric(list.length,'规则待处理事项')}${metric(D.coverage.urls===D.counts.ads?3:4,'数据缺口类别')}${metric(S.material_ok.length,'已确认素材文案组')}</div><section><div class="section-head"><h2>规则与当前配置的差异</h2>${badge(list.length?'需要处理':'暂无已判定差异',list.length?'amber':'green')}</div>${list.length?list.map(x=>`<article class="issue"><div class="section-head">${badge(x.type,'amber')}${btn('去调整规则','step','quiet',`data-index="${x.step}"`)}</div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p>${x.ads?(x.landing?landingAdList(x.ads,x.landing_checks):nameList(x.ads)):''}</article>`).join(''):'<p>已确认的规则暂未发现差异。未确认规则和未取回的数据仍然待处理，不代表整个账户已通过。</p>'}</section><section><h2>这些是没读全，不是已经投错</h2><div class="gap-list">${D.coverage.urls<D.counts.ads?`<div><b>落地页</b><p>${D.counts.ads-D.coverage.urls} 条广告检查不到实际页面。</p></div>`:''}<div><b>主页、Instagram 与 Partnership</b><p>Facebook 帖子归属已识别；Instagram 已关联 ${D.identity_summary.instagram_named_count||0} / ${D.counts.ads} 条广告的账号名称。Partnership 双方完整身份仍待核验，不能视为完整身份已通过。</p></div><div><b>文案与素材</b><p>${D.counts.ads-D.coverage.body} 条广告未取回正文；${D.material_groups.length} 组有可见搭配可供确认，图像含义和完整视频仍需人工查看。</p></div><div><b>UTM</b><p>UTM 目前检查不到。</p></div></div>${check('gap_ack','已了解这些未完成项，允许先保存试运行首日版本','待处理问题会原样保留；不会变成“无问题”，也不会修改 Meta 后台。')}</section>`;}
function missingStep(label){
 if(/页面|落地页/.test(label))return 2;
 if(/确认人|范围|Campaign 状态/.test(label))return 0;
 if(/待补查/.test(label))return 3;
 return 1;
}
function baselineView(){
 const missing=readiness(),list=issues(),complete=stageDone(4);
 const pageReady=S.page_mode==='inherit'?(D.landing_groups||[]).every(g=>S.landing_group_ok.includes(g.key)):(S.pages.length&&S.pages.every(r=>r.confirmed));
 return `<section class="baseline-hero"><div class="version-symbol">${complete?'✓':'05'}</div><div><div class="eyebrow">首次接入 · 最后一步</div><h2>${complete?'首次接入已完成': '保存你的第一份检查标准'}</h2><p>${complete?'首日试运行版本已保存在本机。已确认的规则和当前配置已留存，待处理问题继续保留。':'前面的确认会和今天的广告配置一起保存。完成接入不代表所有广告都没有问题。'}</p></div>${badge(complete?'已保存 · 试运行':'待保存',complete?'green':'amber')}</section>
 <section id="finish-onboarding"><h2>${complete?'接下来做什么':'最后确认，然后完成接入'}</h2>
 ${!complete?`<div class="notice subtle"><strong>页面接入方式：${S.page_mode==='inherit'?'使用已确认的当前落地页':'使用已确认的页面匹配规则'}</strong><p>${S.page_mode==='inherit'?`你已确认 ${(D.landing_groups||[]).filter(g=>S.landing_group_ok.includes(g.key)).length} / ${(D.landing_groups||[]).length} 组页面。保存后，新增广告或更换页面会再次提醒确认。`:'以后按已确认的名称条件核对对应落地页。'}这里确认的是后续检查方式，不会修改广告。</p>${pageReady?check('page_reviewed',S.page_mode==='inherit'?'确认用这批已核对的落地页，作为第一次检查的对照':'确认按已核对的页面规则进行检查'):btn('去确认落地页分组','step','primary','data-index="2"')}</div>`:''}
 ${missing.length?`<div class="notice amber"><strong>还需完成 ${missing.length} 项</strong>${missing.map(label=>`<div class="version-row"><span>${esc(label)}</span>${label==='确认页面接入方式'&&pageReady?'<span>勾选上方确认项即可</span>':btn('去处理 →','step','secondary',`data-index="${missingStep(label)}"`)}</div>`).join('')}</div>`:complete?'<div class="notice success"><strong>这次接入已经保存，不需要重复填写。</strong><p>点击下方按钮，查看这次接入的真实检查结果。下一次取数后再比较调整；当前尚未开启自动每日检查。</p></div>':'<div class="notice success"><strong>确认已齐，可以完成首次接入。</strong><p>下方的问题和检查不到的内容会随版本保存，不会被当作已通过。</p></div>'}
 <div class="actions">${complete?btn('查看第一天检查报告 →','first-day','primary'):btn('完成首次接入，保存首日版本','publish','primary',missing.length?'disabled':'')}${btn('下载当前确认草稿','export-draft')}</div><div id="publish-result" aria-live="polite"></div>
 <p class="muted">本次保存的是首日试运行版本。它可保留规则和配置作为后续对照；数据缺口仍然标记为检查不到，不会宣称全量检查通过。</p></section>
 <div class="rule-grid"><section><h2>已确认的规则</h2><ul class="summary-list"><li>市场：${S.markets.filter(r=>r.confirmed).length} / ${S.markets.length} 组</li><li>语言：${S.languages.filter(r=>r.confirmed).length} / ${S.languages.length} 组</li><li>预算：${S.budget?'已确认当前金额':'待确认'}</li><li>Facebook 主页：${S.identity_rules.filter(r=>r.confirmed).length} / ${S.identity_rules.length} 组</li><li>Instagram：${S.instagram_rules.filter(r=>r.confirmed).length} / ${S.instagram_rules.length} 组</li><li>页面：${S.page_mode==='inherit'?`当前页面 ${S.landing_group_ok.length} 组已确认`:`${S.pages.filter(r=>r.confirmed).length} 条规则已确认`}；检查方式${S.page_reviewed?'已确认':'尚未确认'}</li><li>素材文案：${S.material_ok.length} 组人工确认；其余按当前配置留档，不代表搭配已通过审核</li><li>确认人：${esc(S.reviewer||'未填写')}</li></ul></section>
 <section><h2>保存后仍需处理</h2><p>${list.length} 项规则问题继续保留；完成接入不会把它们加入允许清单。</p>${list.map(item=>`<div class="version-row"><div><b>${esc(item.title)}</b><small>${esc(item.detail)}</small></div>${btn('查看','step','secondary','data-index="3"')}</div>`).join('')||'<p>当前没有发现规则不符。</p>'}<p class="muted">合作双方身份，以及未完成的素材文案核验，继续列在检查范围说明中。</p>${btn('查看全部问题与检查范围','step','secondary','data-index="3"')}</section></div>
 <section><h2>本机保存的版本</h2>${versions.length?versions.slice().reverse().map(v=>`<div class="version-row"><div><b>${esc(v.version)} · 首日试运行版本</b><small>${esc(v.reviewer)} · ${new Date(v.created_at).toLocaleString('zh-CN')}</small></div>${btn('下载版本','export-version','secondary',`data-version="${v.version}"`)}</div>`).join(''):'<p class="muted">尚未保存首日版本；前面的填写内容已自动保存为草稿。</p>'}</section>`;
}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){saved='正在保存…';const snapshot=JSON.parse(JSON.stringify(S));queue=queue.catch(()=>{}).then(async()=>{const result=await fetchJSON('/api/state',{revision,state:snapshot});revision=result.revision;saved='已保存到本机';const el=$('.save-state');if(el)el.textContent=saved;}).catch(e=>{saved='保存失败 · 请勿关闭页面';const el=$('.save-state');if(el)el.textContent=saved;toast(e.message);throw e;});return queue;}
function update(){save().catch(()=>{});render();}
function go(n){S.step=Math.max(0,Math.min(4,n));update();window.scrollTo({top:0,behavior:'smooth'});}
function exportJSON(value,name){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),2000);}
function inputChange(t, draw=true){
 if(!['gap_ack','page_reviewed'].includes(t.dataset.root))S.gap_ack=false;
 if(t.dataset.root){S[t.dataset.root]=t.type==='checkbox'?t.checked:t.value;}
 else if(t.dataset.materialNote){S.material_flags[t.dataset.materialNote]=t.value;}
 else if(t.dataset.igCountry){const r=S.instagram_rules.find(r=>r.country===t.dataset.igCountry),id=t.dataset.igId;r.allowed_ids=t.checked?[...new Set([...r.allowed_ids,id])]:r.allowed_ids.filter(x=>x!==id);r.confirmed=false;}
 else if(t.dataset.identityCountry){const r=S.identity_rules.find(r=>r.country===t.dataset.identityCountry);const pid=t.dataset.identityPage;r.allowed_fb_ids=t.checked?[...new Set([...r.allowed_fb_ids,pid])]:r.allowed_fb_ids.filter(x=>x!==pid);r.confirmed=false;}
 else if(t.dataset.group){const r=S[t.dataset.group][+t.dataset.index];r[t.dataset.field]=t.value;r.confirmed=false;}
 else if(t.dataset.feature){S.allowed_features=t.checked?[...new Set([...S.allowed_features,t.dataset.feature])]:S.allowed_features.filter(f=>f!==t.dataset.feature);S.features=false;}
 else if(t.dataset.page!==undefined){const r=S.pages[+t.dataset.page];r[t.dataset.field]=t.type==='checkbox'?t.checked:t.value;r.confirmed=false;S.page_reviewed=false;}
 else if(t.name==='page_mode'){S.page_mode=t.value;S.page_reviewed=false;if(t.value==='rules'&&!S.pages.length)addPage();}
 else return;
 if(draw)update();else save().catch(()=>{});
}
function addPage(){S.pages.push({field:'campaign',op:'contains',value:'',second:false,field2:'adset',op2:'contains',value2:'',url:'',confirmed:false});}
function refreshLive(t){
 if(t.dataset.group){const r=S[t.dataset.group][+t.dataset.index],card=t.closest('.group-card'),cs=campaignsFor(r);card.querySelector('.match-count').textContent=`匹配 ${cs.length} 个 Campaign · ${adsFor(r).length} 条 Ad`;const status=card.querySelector('.badge');status.textContent='待确认';status.className='badge amber';card.classList.remove('confirmed');card.querySelector('[data-action=confirm-group]').textContent='这组没问题';card.querySelector('details').innerHTML=`<summary>看这组 Campaign</summary>${cs.map(c=>`<div class="name-row">${esc(c.name)}<small>实际国家：${c.countries.join(', ')} · ${c.ad_count} 条 Ad</small></div>`).join('')||'<p>没有匹配到 Campaign。</p>'}`;}
 if(t.dataset.page!==undefined){const r=S.pages[+t.dataset.page],card=t.closest('.page-rule'),aa=pageAds(r),preview=landingChecks(aa,[{...r,confirmed:true}]);card.querySelector('.match-count').textContent=`匹配 ${aa.length} 条 Ad；预览：${preview.filter(c=>c.status==='MATCH').length} 条页面相符，${preview.filter(c=>c.status==='URL_MISMATCH').length} 条页面不同。确认后才按此规则判断。`;card.querySelector('.names').outerHTML=landingAdList(aa);card.querySelector('[data-action=confirm-page]').textContent='确认这条对应关系';const status=card.querySelector('.badge');status.textContent='待确认';status.className='badge amber';const c=document.querySelector('[data-root=page_reviewed]');if(c)c.checked=false;const summary=document.querySelector('#landing-check-summary');if(summary){const all=landingChecks(D.ads,S.pages);summary.textContent=`${all.filter(c=>c.status==='MATCH').length} 条符合已确认规则 · ${all.filter(c=>c.status==='URL_MISMATCH').length} 条页面不符 · ${all.filter(c=>!['MATCH','URL_MISMATCH'].includes(c.status)).length} 条尚未完成核对`;}}

}
const textField=t=>t.matches('input:not([type=checkbox],[type=radio]),textarea');
document.addEventListener('change',e=>{inputChange(e.target,!textField(e.target));if(textField(e.target))refreshLive(e.target);});
document.addEventListener('input',e=>{if(textField(e.target)){inputChange(e.target,false);refreshLive(e.target);}});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(['confirm-groups','confirm-group','add-group','remove-group','allow-observed','confirm-features','add-page','remove-page','confirm-page','confirm-material','flag-material','confirm-material-page','confirm-identity','confirm-identities','confirm-instagram','confirm-landing-group','confirm-all-landing','use-landing-suggestions'].includes(action))S.gap_ack=false;
 if(action==='first-day'){location.href='first-day/';return;}
 if(action==='step')return go(+b.dataset.index);
 if(action==='next')return go(S.step+1);
 if(action==='prev')return go(S.step-1);
 if(action==='tab'){tab=b.dataset.tab;render();return;}
 if(action==='confirm-instagram'){const r=S.instagram_rules.find(r=>r.country===b.dataset.country);if(!r.allowed_ids.length)return toast('请至少选择一个允许的 Instagram 账号。');r.confirmed=!r.confirmed;}
 if(action==='confirm-identity'){const r=S.identity_rules.find(r=>r.country===b.dataset.country);if(!r.allowed_fb_ids.length)return toast('请至少选择一个允许的主页。');r.confirmed=!r.confirmed;}
 if(action==='confirm-identities'){if(S.identity_rules.some(r=>!r.allowed_fb_ids.length))return toast('请先为每个国家选择允许的主页。');S.identity_rules.forEach(r=>r.confirmed=true);}
 if(action==='confirm-groups'){const rs=S[b.dataset.key];if(rs.some(r=>!r.pattern.trim()||!r.value.trim()||!campaignsFor(r).length))return toast('先补齐筛选条件，并确认每组都匹配到 Campaign。');rs.forEach(r=>r.confirmed=true);}
 if(action==='confirm-group'){const r=S[b.dataset.key][+b.dataset.index];if(!r.confirmed&&(!r.pattern.trim()||!r.value.trim()||!campaignsFor(r).length))return toast('先填写完整，并确保能匹配到 Campaign。');r.confirmed=!r.confirmed;}
 if(action==='remove-group'){if(S[b.dataset.key].length===1)return toast('至少保留一组规则。');S[b.dataset.key].splice(+b.dataset.index,1);}
 if(action==='add-group')S[b.dataset.key].push({pattern:'',value:'',confirmed:false});
 if(action==='confirm-landing-group'){const k=b.dataset.key;S.landing_group_ok=S.landing_group_ok.includes(k)?S.landing_group_ok.filter(x=>x!==k):[...S.landing_group_ok,k];S.page_reviewed=false;}
 if(action==='confirm-all-landing'){S.landing_group_ok=D.landing_groups.map(g=>g.key);S.page_reviewed=false;}
 if(action==='use-landing-suggestions'){const proposed=D.landing_groups.flatMap(g=>g.suggested_rules);const signature=r=>JSON.stringify([r.field,r.op,r.value,r.second,r.field2,r.op2,r.value2,r.url]);const seen=new Set(S.pages.filter(r=>r.value.trim()||r.url.trim()).map(signature));S.pages=S.pages.filter(r=>r.value.trim()||r.url.trim());for(const r of proposed)if(!seen.has(signature(r))){S.pages.push({...r,confirmed:false});seen.add(signature(r));}S.page_mode='rules';S.page_reviewed=false;}
 if(action==='allow-observed'){S.allowed_features=[...new Set([...S.allowed_features,...D.features.filter(f=>f.count).map(f=>f.key)])];S.features=false;}
 if(action==='confirm-features'){S.features=!S.features;S.feature_rule_keys=D.features.filter(f=>f.checkable).map(f=>f.key);}
 if(action==='add-page')addPage();
 if(action==='remove-page')S.pages.splice(+b.dataset.index,1);
 if(action==='confirm-page'){const r=S.pages[+b.dataset.index];if(!r.confirmed){try{if(!pageAds(r).length||!r.url.trim())throw Error();for(const u of r.url.trim().split(/\n/)){const url=new URL(u.trim());if(!['https:','http:'].includes(url.protocol))throw Error();}}catch{return toast('请填写完整网址，并确保筛选条件匹配到广告。');}}r.confirmed=!r.confirmed;}
 if(action==='flag-material'){const k=b.dataset.key;if(S.material_flags[k])delete S.material_flags[k];else{S.material_flags[k]='素材与文案需要负责人复核';S.material_ok=S.material_ok.filter(x=>x!==k);}}
 if(action==='confirm-material'){const k=b.dataset.key;delete S.material_flags[k];S.material_ok=S.material_ok.includes(k)?S.material_ok.filter(x=>x!==k):[...S.material_ok,k];}
 if(action==='confirm-material-page'){S.material_ok=[...new Set([...S.material_ok,...D.material_groups.slice(page*6,(page+1)*6).filter(g=>!S.material_flags[g.key]).map(g=>g.key)])];toast('本页未标记复核的搭配已确认，其他页不变。');}
 if(action==='material-prev'){page--;render();return;}
 if(action==='material-next'){page++;render();return;}
 if(action==='export-draft'){exportJSON({kind:'DRAFT',formal_baseline_published:false,...S,coverage:D.coverage,issues:issues()},'demo-DE-接入草稿.json');return;}
 if(action==='export-version'){exportJSON({...versions.find(v=>v.version===b.dataset.version),source_snapshot:D},`demo-DE-${b.dataset.version}.json`);return;}
 if(action==='publish'){
  b.disabled=true;
  try{await save();const v=await fetchJSON('/api/versions',{revision});versions=await fetchJSON('/api/versions');location.href='first-day/?version='+encodeURIComponent(v.version);}catch(e){toast(e.message);b.disabled=false;}return;
 }
 update();
});
try {D=await fetchJSON('data.json');const state=await fetchJSON('/api/state');versions=await fetchJSON('/api/versions');revision=state.revision;if(state.state&&state.state.snapshot_id!==D.snapshot_id)throw Error('保存的确认与本次配置不一致，请检查本地版本。');S={...defaults(),...(state.state||{})};const entryStep=new URLSearchParams(location.search).get('step');if(entryStep!==null&&/^[0-4]$/.test(entryStep))S.step=Number(entryStep);render();}catch(e){$('#app').innerHTML=`<div class="loading"><h1>暂时无法打开接入页</h1><p>${esc(e.message)}</p><p>请使用本地服务地址打开，不要直接双击 HTML。</p></div>`;}
